//! 🧪️ Actual framework registration rows remain shared through a mounted lease and close with exact physical receipts.
use super::*;
use semio_framework_job::*;
use semio_framework_value::{ValueError,ValueRefusalKind};
const TURN:RetainedCloneGrant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:4096,maximum_release_bytes:4096,maximum_depth:4096};
#[test]
fn actual_declared_tools_share_original_factories_and_retire_under_original_caller(){let mut definition=semio_framework_async::poll::resolve_ready(semio_framework_manifest_app_surface::testkit::app_with(Vec::new(),Vec::new()));definition.id=<crate::fixture::NativeWindowApp as ArtifactApp>::APP_ID.into();definition.controller_id=definition.id.clone();definition.dialect=<crate::fixture::NativeWindowApp as ArtifactApp>::DIALECT.into();definition.io.artifact_schema=<crate::fixture::NativeWindowApp as ArtifactApp>::DOCUMENT_SCHEMA.into();let mut definition=semio_framework_plugin_window_kits::RegisteredAppDefinition::declared(definition,true);let catalog=produce_declared_tool_catalog::<crate::fixture::NativeWindowApp>(definition.original_source().unwrap()).unwrap();let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();assert_eq!(catalog.controller_id,law["controller"].as_str().unwrap());let expected_ids=law["frameworkTools"].as_array().unwrap().iter().map(|id|id.as_str().unwrap()).collect::<std::collections::BTreeSet<_>>();assert_eq!(catalog.framework.iter().map(|(id,_)|id.as_str()).collect::<std::collections::BTreeSet<_>>(),expected_ids);let expected=&catalog.framework.get(0).unwrap().1 as *const _ as usize;let id=catalog.framework.get(0).unwrap().0.clone();let mut source=OriginalDeclaredTools::new(catalog);let(refused,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||DeclaredToolCatalogAlias::admit(source.source().unwrap(),TURN));assert!(refused.is_err());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));definition.commit_producer();source.commit_producer();let row_key=source.source().unwrap().row_key(semio_framework_plugin_job::original_declared_tools::DeclaredToolRole::Framework,0).unwrap().unwrap();let mut caller=OriginalJobFixtureCaller::admit(OperationId(78221),Generation(9),RetainedCloneGrant{maximum_items:1<<24,maximum_copy_bytes:1<<28,maximum_capacity_bytes:1<<26,maximum_release_bytes:1<<27,maximum_depth:4096},default_now_us,u64::MAX,1<<24);let mut decoder=OriginalJobDecodeOwner::empty();let mut alias=None;let d=DeclaredToolCatalogAlias::birth_demands();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(TURN,&mut decoder,|cx|{let grant=cx.retained_grant();admit_original_construction(cx,&mut alias,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:0,depth:d.depth},|_|Ok(DeclaredToolCatalogAlias::admit(source.source().unwrap(),grant)?.unwrap()))?;Ok(())}));result.unwrap();assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(alias.as_ref().unwrap().catalog().unwrap().framework(&id).unwrap()as *const _ as usize,expected);let mut foreign_catalog=OriginalDeclaredTools::new(produce_declared_tool_catalog::<crate::fixture::NativeWindowApp>(definition.original_source().unwrap()).unwrap());foreign_catalog.commit_producer();let foreign_key=foreign_catalog.source().unwrap().row_key(semio_framework_plugin_job::original_declared_tools::DeclaredToolRole::Framework,0).unwrap().unwrap();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||alias.as_ref().unwrap().row(foreign_key));assert!(result.is_err());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));for index in 0..65536{if foreign_catalog.terminal_is_empty(){break}let d=foreign_catalog.close_demands(4096).unwrap();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(TURN,&mut decoder,|cx|cx.with_original_retirement(|cx|close_original_retained_step(cx,d,|g|foreign_catalog.close_step(g)))));let p=result.unwrap().progress();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));assert!(index<65535)}let original_row=match alias.as_ref().unwrap().row(row_key).unwrap(){semio_framework_plugin_job::original_declared_tools::DeclaredToolRow::Framework(row)=>row as *const _ as usize,_=>panic!("original registered row role changed")};assert_eq!(original_row,expected);let(borrowed,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||alias.as_ref().unwrap().source().unwrap().framework(&id).unwrap()as *const _ as usize);assert_eq!(borrowed,expected);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let d=source.close_demands(4096).unwrap();let p=caller.turn_with_decoder(TURN,&mut decoder,|cx|close_original_retained_step(cx,d,|g|source.close_step(g))).unwrap().progress();assert_eq!(p,Default::default());assert!(!source.terminal_is_empty());close_generic_proof_alias(source.source().unwrap(),&mut caller,&mut decoder);caller.cancel().cancel_now();for turn in 0..65536{if alias.as_ref().unwrap().terminal_is_empty(){break}let owner=alias.as_mut().unwrap();let d=owner.close_demands(4096).unwrap();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(TURN,&mut decoder,|cx|cx.with_original_retirement(|cx|close_original_retained_step(cx,d,|g|owner.close_step(g)))));let p=result.unwrap().progress();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));assert!(turn<65535)}assert!(alias.take().unwrap().terminal_is_empty());for turn in 0..65536{if source.terminal_is_empty(){break}let d=source.close_demands(4096).unwrap();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(TURN,&mut decoder,|cx|cx.with_original_retirement(|cx|close_original_retained_step(cx,d,|g|source.close_step(g)))));let p=result.unwrap().progress();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));assert!(turn<65535,"original tool source retained demand={d:?}, progress={p:?}")}assert!(source.terminal_is_empty());for turn in 0..65536{if definition.terminal_is_empty(){break}let d=definition.close_demands(4096).unwrap();caller.turn_with_decoder(TURN,&mut decoder,|cx|cx.with_original_retirement(|cx|close_original_retained_step(cx,d,|g|definition.close_step(g)))).unwrap();assert!(turn<65535)}while !decoder.terminal_is_empty(){caller.turn(TURN,|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(4096)?;close_original_retained_step(cx,d,|g|decoder.close_step(g))?;Ok(())})).unwrap();}caller.retire(TURN);}

fn close_generic_proof_alias(source:DeclaredToolCatalogSource<'_>,caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner){
 type Alias=semio_framework_plugin_job::original_declared_tools::DeclaredToolRegistrationAlias;type Close=semio_framework_value::retirement::controlled::ControlledRetirement<Alias>;
 for adopt in [false,true]{
 let key=source.row_key(semio_framework_plugin_job::original_declared_tools::DeclaredToolRole::Framework,0).unwrap().unwrap();let expected=&source.framework.get(0).unwrap().1 as *const _ as usize;let mut alias=None;if adopt{let mut original=None;let d=DeclaredToolCatalogAlias::birth_demands();caller.turn_with_decoder(TURN,decoder,|cx|{let grant=cx.retained_grant();admit_original_construction(cx,&mut original,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth},|_|DeclaredToolCatalogAlias::admit(source,grant)?.ok_or_else(||ValueError::literal(ValueRefusalKind::InvariantViolated,"funded original lookup alias was not admitted")))?;Ok(())}).unwrap();let d=Alias::adoption_demands();for denied in [RetainedCloneGrant{maximum_items:0,..TURN},RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..TURN},RetainedCloneGrant{maximum_depth:d.depth-1,..TURN}]{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(denied,decoder,|cx|{let grant=cx.retained_grant();admit_original_construction(cx,&mut alias,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:0,release_bytes:0,depth:d.depth},|_|Alias::adopt(&mut original,key,grant)?.ok_or_else(||ValueError::literal(ValueRefusalKind::InvariantViolated,"funded original registration donation was refused")))?;Ok(())}));result.unwrap();assert!(alias.is_none());assert!(original.is_some());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}caller.turn_with_decoder(TURN,decoder,|cx|{let grant=cx.retained_grant();admit_original_construction(cx,&mut alias,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:0,release_bytes:0,depth:d.depth},|_|Alias::adopt(&mut original,key,grant)?.ok_or_else(||ValueError::literal(ValueRefusalKind::InvariantViolated,"funded original registration donation was refused")))?;Ok(())}).unwrap();assert!(original.is_none());}else{let d=Alias::birth_demands();caller.turn_with_decoder(TURN,decoder,|cx|{let grant=cx.retained_grant();admit_original_construction(cx,&mut alias,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth},|_|Alias::admit(source,key,grant)?.ok_or_else(||ValueError::literal(ValueRefusalKind::InvariantViolated,"funded original proof alias was not admitted")))?;Ok(())}).unwrap();}
 assert_eq!(&**alias.as_ref().unwrap()as *const _ as usize,expected);
 let mut retirement=None;let d=RetirementDemand{copy_bytes:2*size_of::<Alias>()+size_of::<Close>(),depth:1,..Default::default()};caller.turn_with_decoder(TURN,decoder,|cx|{admit_original_construction(cx,&mut retirement,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:0,release_bytes:0,depth:d.depth},|_|{let owner=Close::new(alias.take().unwrap()).map_err(|(error,_)|error)?;Ok((owner,RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})?;Ok(())}).unwrap();
 let owner=retirement.as_mut().unwrap();for index in 0..65536{if owner.terminal_is_empty(){break}let d=owner.select(4096).unwrap().demands();for axis in 0..5{let mut denied=TURN;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes=d.copy_bytes-1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes=d.capacity_bytes-1,3 if d.release_bytes>0=>denied.maximum_release_bytes=d.release_bytes-1,4 if d.depth>0=>denied.maximum_depth=d.depth-1,_=>continue}let selected=owner.select(4096).unwrap();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(denied,decoder,|cx|cx.with_original_retirement(|cx|close_original_retained_step(cx,d,|g|selected.step(g)))));assert_eq!(result.unwrap().progress(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}
 let selected=owner.select(4096).unwrap();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(TURN,decoder,|cx|cx.with_original_retirement(|cx|close_original_retained_step(cx,d,|g|selected.step(g)))));let p=result.unwrap().progress();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));assert!(index<65535,"original registered proof alias retained its actual closure graph: {d:?}");}
}
}
